// Typed access to the DDI-Net 3.0 measurement reports. The JSON is generated by
// tools/build_v3_facts.py from reports/v3_*.json; nothing here is hand-typed.
import raw from "./v3facts.json";

export interface DirectionRow {
  template: string;
  n_informative: number;
  n_consistent: number;
  n_reversed: number;
  consistency: number | null;
  status: "consistent" | "unverified" | "symmetric";
}

export interface CoverageGroup {
  n_pairs: number; prevalence: number;
  auroc_mean: number; auroc_sd: number; auprc_mean: number; auprc_sd: number; n_seeds: number;
}

export interface V3Facts {
  direction_audit: {
    source: string;
    verified_threshold: number;
    n_records: number;
    records_by_status: { symmetric: number; consistent: number; unverified: number };
    pk_types: Record<string, DirectionRow>;
  };
  seed_disagreement: {
    source: string;
    views: Record<"pooled" | "S3", {
      n_pairs: number;
      auroc_sd_detects_error: number;
      auroc_sd_detects_error_ci95: number[];
      auroc_margin_detects_error: number;
      spearman_sd_abs_error: number;
    }>;
  };
  coverage_reliability: {
    source: string;
    views: Record<"pooled" | "S3", Record<"both_annotated" | "at_least_one_unannotated", CoverageGroup>>;
  };
}

export const v3facts = raw as V3Facts;
